<script setup lang="ts">
import {localize} from './localization';

import {computed,inject,nextTick,ref,watch} from 'vue';
import {surfaceDimensions,type ModelDimensions} from '../../../packages/surface/dimensions';
import {validSpeciesParameters,validBodyParameters} from '../../../packages/body/parameter-validation';
import ModelSourceDialog from './ModelSourceDialog.vue';
import {useSession} from './store';
import {useDraftHistory} from './modules/useDraftHistory';
import CustomTemplatePanel from './CustomTemplatePanel.vue';
import MeshEditPanel from './MeshEditPanel.vue';
import {speciesDefaults} from '../../../packages/body/defaults';
import {vDecimal} from './modules/decimal-input';
import {measurementLabel,modelPartLabel} from './modules/model-labels';
import type {SpeciesParams,BodyParams} from '../../../packages/schema/index';
const props=defineProps<{language:'zh'|'en'}>(),advanced=inject('advancedMode',ref(false)),store=useSession(),zh=computed(()=>props.language==='zh'),surface=computed(()=>store.data.project?.surface),scale=ref(1),showBody=ref(false);
const speciesNames:Record<string,string>={canine:'犬科',feline:'猫科',rabbit:'兔',bear:'熊',deer:'鹿',dragon:'龙'};
const speciesLabels:Record<string,string>={heightMm:'总身高 mm',neckGirthMm:'颈围 mm',chestGirthMm:'胸围 mm',waistGirthMm:'腰围 mm',hipGirthMm:'臀围 mm',shoulderWidthMm:'肩宽 mm',armLengthMm:'臂长 mm',legLengthMm:'腿长 mm',headWidthMm:'头宽 mm',headLengthMm:'头部高度 mm',snoutLengthMm:'口鼻长度 mm',snoutWidthMm:'口鼻宽度 mm',earHeightMm:'耳高 mm',earWidthMm:'耳宽 mm',earAngleRad:'耳外倾角 rad',tailLengthMm:'尾中心线长 mm',tailBaseGirthMm:'尾根围度 mm',tailTipGirthMm:'尾尖围度 mm',tailCurvature:'尾曲率比例',upperArmGirthMm:'上臂围 mm',forearmGirthMm:'前臂围 mm',thighGirthMm:'大腿围 mm',shinGirthMm:'小腿围 mm',pawLengthMm:'手爪长度 mm',pawWidthMm:'手足宽度 mm',footLengthMm:'足长 mm',clawLengthMm:'爪长 mm',paddingMm:'全局填充 mm',layerMm:'参考面层厚 mm'};
const showSpecies=ref(false),speciesParams=ref<SpeciesParams>(speciesDefaults('canine'));
const speciesGroups=[{zh:'身体尺寸',en:'Body dimensions',keys:['heightMm','neckGirthMm','chestGirthMm','waistGirthMm','hipGirthMm','shoulderWidthMm']},{zh:'四肢与手足',en:'Limbs & paws',keys:['armLengthMm','legLengthMm','upperArmGirthMm','forearmGirthMm','thighGirthMm','shinGirthMm','pawLengthMm','pawWidthMm','footLengthMm','clawLengthMm']},{zh:'头部与耳尾',en:'Head, ears & tail',keys:['headWidthMm','headLengthMm','snoutLengthMm','snoutWidthMm','earHeightMm','earWidthMm','earAngleRad','tailLengthMm','tailBaseGirthMm','tailTipGirthMm','tailCurvature']},{zh:'填充与层厚',en:'Padding & layer',keys:['paddingMm','layerMm']}];
const layerMaterial=ref('');
function useMaterialLayer(){const m=store.data.project?.materials?.find(m=>m.id===layerMaterial.value);if(m)speciesParams.value.layerMm=m.compensationMm;}
function setSpecies(species:SpeciesParams['species']){speciesParams.value=speciesDefaults(species);}
async function assemble(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.assembleSpecies(p.id,p.revision));}
const speciesValid=computed(()=>validSpeciesParameters(speciesParams.value));
const bodyValid=computed(()=>validBodyParameters(params.value));
async function generateTemplate(){const p=store.data.project;if(p&&speciesValid.value)await store.run(()=>window.fpcad.generateSpecies(p.id,p.revision,JSON.parse(JSON.stringify(speciesParams.value))));}
const params=ref<BodyParams>({heightMm:600,neckGirthMm:500,chestGirthMm:1100,waistGirthMm:900,hipGirthMm:1000,depthRatio:.7,chestPaddingMm:0,waistPaddingMm:0,hipPaddingMm:0,layerMm:0});
const names:Record<keyof BodyParams,[string,string]>={heightMm:['躯干高度 mm','Torso height mm'],neckGirthMm:['颈围 mm','Neck girth mm'],chestGirthMm:['胸围 mm','Chest girth mm'],waistGirthMm:['腰围 mm','Waist girth mm'],hipGirthMm:['臀围 mm','Hip girth mm'],depthRatio:['前后深度 / 左右宽度','Depth / width ratio'],chestPaddingMm:['胸部填充 mm','Chest padding mm'],waistPaddingMm:['腰部填充 mm','Waist padding mm'],hipPaddingMm:['臀部填充 mm','Hip padding mm'],layerMm:['制造参考面层厚 mm','Manufacturing surface layer mm']};
async function exportMesh(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.exportSurface(p.id,p.revision));}
async function importPattern(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.importPattern(p.id,p.revision,scale.value));}
const sourceDialog=ref<InstanceType<typeof ModelSourceDialog>>(),sourceNotice=ref(''),speciesForm=ref<HTMLElement>(),speciesSelect=ref<HTMLSelectElement>();
function openSource(){if(store.busy||!store.data.project)return;sourceNotice.value='';sourceDialog.value?.open();}
async function chooseTemplate(){if(store.busy)return;sourceDialog.value?.close();showSpecies.value=true;showBody.value=false;await nextTick();speciesForm.value?.scrollIntoView({block:'start'});speciesSelect.value?.focus({preventScroll:true});}
async function importMesh(){const p=store.data.project;if(!p||store.busy)return;sourceNotice.value='';const imported=await store.run(()=>window.fpcad.importSurface(p.id,p.revision,scale.value));if(imported){await nextTick();sourceDialog.value?.close();}else sourceNotice.value=store.error?(zh.value?'导入失败：':localize('Import failed: '))+store.error:(zh.value?'未选择文件。可以重新导入或使用内置模板。':localize('No file selected. Try again or use a built-in template.'));}
defineExpose({openSource});
async function generate(){const p=store.data.project;if(p&&bodyValid.value)await store.run(()=>window.fpcad.generateBody(p.id,p.revision,JSON.parse(JSON.stringify(params.value))));}

const dimensions=computed(()=>surface.value?surfaceDimensions(surface.value):undefined),modelDimensions=computed(()=>dimensions.value?Object.values(dimensions.value):[]);
const sizeMode=ref<'dimensions'|'uniform'>('dimensions'),requestedSize=ref<ModelDimensions>({width:0,height:0,depth:0}),uniformScale=ref(1),sizeNotice=ref('');
const canConstrainBody=computed(()=>surface.value?.source==='species-template-1'&&!!surface.value.template),bodyConstrained=ref(false),bodyTargets=ref<Record<string,number>>({});
const historyPanel=ref<HTMLElement>();
const history=useDraftHistory(()=>({scale:scale.value,species:speciesParams.value,body:params.value,size:requestedSize.value,uniform:uniformScale.value,targets:bodyTargets.value,constrained:bodyConstrained.value,mode:sizeMode.value,material:layerMaterial.value}),v=>{scale.value=v.scale;speciesParams.value=v.species;params.value=v.body;requestedSize.value=v.size;uniformScale.value=v.uniform;bodyTargets.value=v.targets;bodyConstrained.value=v.constrained;sizeMode.value=v.mode;layerMaterial.value=v.material;},()=>!!historyPanel.value?.getClientRects().length,()=>store.busy);
watch(()=>JSON.stringify([surface.value?.id,surface.value?.source]),()=>{history.reset(()=>{bodyConstrained.value=canConstrainBody.value;});},{immediate:true});
watch(()=>JSON.stringify(surface.value?.template?.measurements),()=>{history.reset(()=>{bodyTargets.value=Object.fromEntries((surface.value?.template?.measurements??[]).filter(m=>['height','neckGirth','chestGirth','waistGirth','hipGirth'].includes(m.name)).map(m=>[m.name,m.actualMm]));});},{immediate:true});
const bodyTargetsValid=computed(()=>Object.keys(bodyTargets.value).length===5&&Object.values(bodyTargets.value).every(v=>Number.isFinite(v)&&v>0));
async function applyBodyTargets(){const p=store.data.project;if(!p||!canConstrainBody.value||!bodyConstrained.value||!bodyTargetsValid.value||store.busy)return;sizeNotice.value='';if(await store.run(()=>window.fpcad.fitSpecies(p.id,p.revision,JSON.parse(JSON.stringify(bodyTargets.value)))))sizeNotice.value=zh.value?'已按身体测量重新生成连续模型。请检查花纹位置并重新裁切。':localize('Continuous model regenerated from body measurements. Review pattern positions and regenerate cuts.');}
watch(()=>JSON.stringify([surface.value?.id,surface.value?.topologyVersion]),()=>{history.reset(()=>{const mesh=surface.value;if(!mesh)return;requestedSize.value=surfaceDimensions(mesh);uniformScale.value=1;if(mesh.template)speciesParams.value=JSON.parse(JSON.stringify(mesh.template.parameters));if(mesh.parameters)params.value={...mesh.parameters};});},{immediate:true});
const sizeValid=computed(()=>sizeMode.value==='uniform'?Number.isFinite(uniformScale.value)&&uniformScale.value>0&&uniformScale.value<=100000:!!dimensions.value&&(['width','height','depth'] as const).every(axis=>Number.isFinite(requestedSize.value[axis])&&requestedSize.value[axis]>=0&&requestedSize.value[axis]<=100000&&(dimensions.value![axis]>1e-10?requestedSize.value[axis]>0:requestedSize.value[axis]===0)));
async function resizeModel(){const p=store.data.project;if(!p||!surface.value||bodyConstrained.value||!sizeValid.value||store.busy)return;sizeNotice.value='';const applied=await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'surface.resize',...(sizeMode.value==='uniform'?{scale:uniformScale.value}:{dimensionsMm:{...requestedSize.value}})}));if(applied)sizeNotice.value=zh.value?'模型尺寸已应用。已贴附花纹随网格保留；请重新裁切。':localize('Model dimensions applied. Attached paint follows the mesh; regenerate cuts.');}

</script>
<template><section ref="historyPanel" class="model-tool-section"><ModelSourceDialog ref="sourceDialog" :language="language" :busy="store.busy" v-model:scale="scale" :notice="sourceNotice" @import="importMesh" @template="chooseTemplate"/><div class="source-actions"><button class="primary" :disabled="store.busy" @click="importMesh">{{zh?'导入三角 OBJ / GLB':localize('Import triangulated OBJ / GLB')}}</button><button :class="{active:showSpecies}" :aria-expanded="showSpecies" @click="showSpecies=!showSpecies;showBody=false">{{zh?'物种全身模板':localize('Full-body species templates')}}</button></div><p class="model-dimensions">{{zh?'整体包围框（含手臂、尾巴与翼）':localize('Whole bounding box (includes arms, tail and wings)')}} {{modelDimensions.map(n=>n.toFixed(2)).join(' × ')}} mm ({{modelDimensions.map(n=>(n/10).toFixed(2)).join(' × ')}} cm)</p><details v-if="surface" class="model-size-controls" open><summary>{{zh?'调整模型尺寸':localize('Resize model')}}</summary><label class="body-constraint"><input v-model="bodyConstrained" type="checkbox" :disabled="!canConstrainBody" :aria-label="zh?'遵循身体尺寸约束':localize('Follow body measurement constraints')">{{zh?'遵循身体尺寸约束':localize('Follow body measurement constraints')}}</label><template v-if="bodyConstrained&&canConstrainBody"><p>{{zh?'按头耳至足底身高和躯干围度重新生成，按物种身体配方校验比例与左右对称；胸、腰、臀与颈围不包含手臂、尾巴或翼。下方是包含填充与层厚的实际目标，不是包围框宽深。':localize('Regenerate from head-and-ear-to-sole height and anatomical torso girths, validating species proportions and paired limbs. Girths exclude arms, tail and wings; targets include padding and layers, not bounding-box width/depth.')}}</p><div class="dimension-grid body-targets"><label v-for="(value,key) in bodyTargets" :key="key">{{measurementLabel(String(key),zh)}} mm<input v-decimal v-model.number="bodyTargets[key]" type="number" min=".01" step=".01" :aria-label="'Body '+key+' mm'"></label></div><button class="primary" :disabled="store.busy||!bodyTargetsValid" @click="applyBodyTargets">{{zh?'应用身体测量':localize('Apply body measurements')}}</button></template><template v-else><p>{{zh?'自由缩放设置整个模型的 X 宽、Y 高与 Z 深，包含所有附肢；等比缩放保持三轴比例。内置模型自由缩放后转为通用网格，原身体配方与测量报告不再适用，花纹随网格保留，需重新裁切。':localize('Free resizing changes the whole X/Y/Z bounds, including appendages. Uniform scaling keeps axis proportions. A resized built-in becomes a generic mesh; its body recipe and measurements no longer apply. Paint follows the mesh; regenerate cuts.')}}</p><p v-if="!canConstrainBody">{{zh?'此模型没有有效的内置身体配方，不能推断胸腰臀测量；可自由缩放或使用下方模板。':localize('This mesh has no valid built-in body recipe. Anatomical girths cannot be inferred; resize freely or choose a template below.')}}</p><label>{{zh?'调整方式':localize('Resize mode')}}<select v-model="sizeMode" aria-label="Model resize mode"><option value="dimensions">{{zh?'宽 × 高 × 深':localize('Width × height × depth')}}</option><option value="uniform">{{zh?'等比缩放':localize('Uniform scale')}}</option></select></label><label v-if="sizeMode==='uniform'">{{zh?'倍率':localize('Scale factor')}}<input v-decimal v-model.number="uniformScale" type="number" min=".01" max="100000" step=".01" aria-label="Model uniform scale"></label><div v-else class="dimension-grid"><label v-for="axis in (['width','height','depth'] as const)" :key="axis">{{zh?({width:'整体宽度 X',height:'整体高度 Y',depth:'整体深度 Z'}[axis]):localize(axis)}} mm<input v-decimal v-model.number="requestedSize[axis]" type="number" :min="dimensions?.[axis]===0?0:.01" max="100000" step=".01" :disabled="dimensions?.[axis]===0" :aria-label="'Model '+axis+' mm'"></label></div><small v-if="!sizeValid" role="alert">{{zh?'请输入有效的正数尺寸或缩放倍率；平面模型的零厚度保持为 0。':localize('Enter positive finite sizes or a scale factor. Planar axes remain at zero.')}}</small><button class="primary" :disabled="store.busy||!sizeValid" @click="resizeModel">{{zh?'应用模型尺寸':localize('Apply model size')}}</button></template><p v-if="sizeNotice" role="status">{{sizeNotice}}</p></details><details class="tool-details"><summary>{{zh?'导入与导出选项':localize('Import & export options')}}</summary><p>{{zh?'OBJ 无内置单位：原坐标为 mm 时比例 1，为 cm 时填 10。GLB 自动由米转换为 mm，通常额外倍率保持 1。导入后核对右侧模型尺寸。':localize('OBJ has no encoded unit: use 1 for mm, 10 for cm. GLB metres convert to mm automatically; keep the extra scale at 1. Verify model dimensions after import.')}}</p><label>{{zh?'导入比例（OBJ 每单位 mm；GLB 额外倍率）':localize('Import scale (OBJ mm per unit; GLB extra multiplier)')}}<input v-model.number="scale" type="number" min=".00001" step=".1"></label><button :disabled="store.busy||!surface" @click="exportMesh">{{zh?'导出静态 GLB（米）':localize('Export static GLB (metres)')}}</button></details>
 <p>{{zh?'导入模型或选择模板开始。模板生成会替换当前模型，可撤销。':localize('Import a mesh or choose a template. Generating replaces the model and can be undone.')}}</p>
 <div v-if="showSpecies" ref="speciesForm" class="body-form"><p>{{zh?'生成包含物种部位的连续封闭服装模型，可修改尺寸后重新生成。胸、腰、臀和颈围按躯干参考截面测量，不包含手臂、翼和尾部。制作前请核对尺寸并试做。':localize('Generate a continuous closed costume model with species parts, then change dimensions and regenerate. Chest, waist, hip and neck girths measure the torso reference sections, excluding arms, wings and tail. Verify dimensions and trial the pattern before fabrication.')}}</p><label>{{zh?'材料有效补偿':localize('Material compensation')}}<select v-model="layerMaterial"><option value="">—</option><option v-for="m in store.data.project?.materials??[]" :key="m.id" :value="m.id">{{m.name}} / {{m.compensationMm}} mm</option></select></label><button :disabled="!layerMaterial" @click="useMaterialLayer">{{zh?'将补偿填入参考层厚（生成后生效）':localize('Copy compensation to layer (applies on generation)')}}</button><label>{{zh?'物种':localize('Species')}}<select ref="speciesSelect" :value="speciesParams.species" @change="setSpecies(($event.target as HTMLSelectElement).value as SpeciesParams['species'])"><option v-for="species in ['canine','feline','rabbit','bear','deer','dragon']" :key="species" :value="species">{{zh?speciesNames[species]:localize(species)}}</option></select></label><label>{{zh?'腿型':localize('Leg posture')}}<select v-model="speciesParams.legType"><option value="plantigrade">{{zh?'植行腿':localize('Plantigrade')}}</option><option value="digitigrade">{{zh?'趾行腿':localize('Digitigrade')}}</option></select></label><details v-for="(group,index) in speciesGroups" :key="group.en" class="species-group" :open="index===0"><summary>{{zh?group.zh:localize(group.en)}}</summary><div class="dimension-grid"><label v-for="key in group.keys as (keyof SpeciesParams)[]" :key="key">{{zh?speciesLabels[key]:localize(key.replace(/([A-Z])/g,' $1'))}}<input v-model.number="speciesParams[key]" v-decimal type="number" :step="key.includes('Rad')||key==='tailCurvature'?.01:1"></label></div></details><p v-if="!speciesValid" role="alert">{{zh?'请检查尺寸范围与身体比例。':localize('Check dimension ranges and body proportions.')}}</p><button class="primary" :disabled="store.busy||!speciesValid" @click="generateTemplate">{{zh?'生成 / 更新物种模板':localize('Generate / update species template')}}</button></div>
 <details v-if="surface?.template" class="tool-details"><summary>{{zh?'拼合与测量报告':localize('Assembly & measurements')}}</summary><button :disabled="store.busy||!!surface.assembly" @click="assemble">{{zh?'拼合为连续网格（可撤销）':localize('Assemble continuous shell (undoable)')}}</button><p>{{zh?'以下是部位参考面的尺寸；连续网格身高与躯干围度另列。':localize('Part reference dimensions below; continuous mesh height and torso girths are listed separately.')}}</p><strong>{{zh?(speciesNames[surface.template.parameters.species]+' · '+(surface.template.parameters.legType==='digitigrade'?'趾行腿':'植行腿')):surface.template.id}} v{{surface.template.version}}</strong> · {{surface.template.parts.length}} {{zh?'部件':localize('parts')}}<p>{{surface.template.parts.map(part=>modelPartLabel(part,zh)).join(' · ')}}</p><table><thead><tr><th>{{zh?'测量':localize('Measurement')}}</th><th>{{zh?'目标 mm':localize('Target mm')}}</th><th>{{zh?'实测 mm':localize('Actual mm')}}</th><th>{{zh?'偏差 mm':localize('Δ mm')}}</th></tr></thead><tbody><tr v-for="m in surface.template.measurements" :key="m.name"><td>{{measurementLabel(m.name,zh)}}</td><td>{{m.targetMm.toFixed(2)}}</td><td>{{m.actualMm.toFixed(2)}}</td><td>{{m.residualMm.toFixed(2)}}</td></tr></tbody></table></details>
 <details v-if="surface?.assembly" class="tool-details"><summary>{{zh?'实体拼合报告':localize('Solid assembly report')}}</summary><strong>{{zh?'实体拼合报告':localize('Solid assembly report')}}</strong> · {{surface.assembly.components}} {{zh?'个连续实体':localize('component')}} · {{surface.assembly.volumeMm3.toFixed(2)}} mm³ · {{zh?'累计简化容差':localize('Cumulative simplification tolerance')}} {{surface.assembly.toleranceMm.toFixed(2)}} mm<p>{{zh?'身高取连续网格整体范围；胸、腰、臀和颈围取用于生成模型的躯干截面，排除手臂、翼和尾部。':localize('Height measures the whole continuous mesh. Chest, waist, hip and neck girths measure its torso source sections, excluding arms, wings and tail.')}}</p><table><thead><tr><th>{{zh?'拼合后测量':localize('Assembled measurement')}}</th><th>{{zh?'目标 mm':localize('Target mm')}}</th><th>{{zh?'实测 mm':localize('Actual mm')}}</th><th>{{zh?'偏差 mm':localize('Δ mm')}}</th></tr></thead><tbody><tr v-for="m in surface.assembly.measurements" :key="m.name"><td>{{measurementLabel(m.name,zh)}}</td><td>{{m.targetMm.toFixed(2)}}</td><td>{{m.actualMm.toFixed(2)}}</td><td>{{m.residualMm.toFixed(2)}}</td></tr></tbody></table></details>
 <div v-if="showBody&&advanced" class="body-form"><p>{{zh?'原创固定拓扑躯干曲面，用于测量、填充和展开实验；尚非完整犬猫身体模板。无填充时离散截面周长匹配输入围度。':localize('Original fixed-topology torso surface for measurement, padding and unwrap experiments; not a complete canine/feline template. Without padding, discrete ring girths match inputs.')}}</p><label v-for="(value,key) in params" :key="key">{{localize(names[key][zh?0:1])}}<input v-model.number="params[key]" v-decimal type="number" :step="key==='depthRatio'?.01:1"></label><button :disabled="store.busy||!bodyValid" @click="generate">{{zh?'生成 / 更新躯干':localize('Generate / update torso')}}</button></div>

<CustomTemplatePanel :language="language"/><MeshEditPanel :language="language"/><details v-if="advanced" class="tool-details"><summary>{{zh?'参数躯干（实验）':localize('Parametric torso (experimental)')}}</summary><button @click="showBody=!showBody">{{zh?'设置躯干参数':localize('Set torso parameters')}}</button></details></section></template>
<style scoped>.model-tool-section{padding:15px}.species-form label,.body-form label{display:block;margin:10px 0}.tool-details{margin:14px 0}.dimension-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.species-form input{width:100%}table{font-size:10px;width:100%}td{padding:3px}button{max-width:100%;white-space:normal}</style>

<style scoped>.model-size-controls{border-block:1px solid var(--border);padding:12px 0;margin:12px 0}.model-size-controls label{display:block;margin:10px 0}.model-size-controls input,.model-size-controls select{width:100%}.model-size-controls small{display:block;color:var(--warning);margin:8px 0}.model-size-controls p{line-height:1.6;font-size:11px;color:var(--text-muted)}.model-size-controls button{margin-top:8px}</style>

<style scoped>.body-constraint{display:flex!important;align-items:center;gap:8px}.body-constraint input{width:auto!important}</style>

<style scoped>.source-actions{display:flex;flex-wrap:wrap;gap:8px}.source-actions>button{margin:0}.model-tool-section>details>button,.body-form>button{margin-top:8px}.dimension-grid input{margin-top:5px}</style>
